BEGIN READ ONLY; SELECT jsonb_build_object('players',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.players t),'teams',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.tournament_players t),'rounds',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.rounds t),'matches',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.matches t),'matchHoles',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.match_holes t),'courses',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.tournament_setup_course_holes_v1 t),'playerLinks',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from participant_identity.user_player_links t),'domainPointers',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from production_control.current_tournament_pointer_v1 t),'guide',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.guide_content_revisions t),'tees',(select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(t)order by to_jsonb(t)::text collate "C"),'[]'::jsonb)::text,'sha256'),'hex')from scoring_authority.tournament_setup_course_tees_v1 t),'fixture',(select details->>'fixture_state_sha256'from production_control.operation_audit_events where event_type='CERTIFICATION_MODEL_D_FIXTURE_BOOTSTRAPPED')) AS d9_digests; COMMIT;
